bool CheckDasPrimitiveArrayValues(UScriptStruct* Tree,void* Memory){auto Array=[&](const TCHAR* Name){auto* P=FindDasStructField(Tree,Name);return CastField<FArrayProperty>(P);};auto* Numbers=Array(TEXT("Numbers"));if(!Numbers)return true;auto Values=[&](FArrayProperty* P){return FScriptArrayHelper(P,P->ContainerPtrToValuePtr<void>(Memory));};auto N=Values(Numbers);bool Pass=N.Num()==2 && CastFieldChecked<FIntProperty>(Numbers->Inner)->GetPropertyValue(N.GetRawPtr(0))==-3 && CastFieldChecked<FIntProperty>(Numbers->Inner)->GetPropertyValue(N.GetRawPtr(1))==7;auto* Ratio=Array(TEXT("Ratios"));auto* Precise=Array(TEXT("Precise"));auto* Flags=Array(TEXT("Flags"));auto* Labels=Array(TEXT("Labels"));auto* Names=Array(TEXT("Names"));if(!Ratio || !Precise || !Flags || !Labels || !Names)return false;Pass &= Values(Ratio).Num()==1 && CastFieldChecked<FFloatProperty>(Ratio->Inner)->GetPropertyValue(Values(Ratio).GetRawPtr(0))==1.25f;Pass &= Values(Precise).Num()==1 && CastFieldChecked<FDoubleProperty>(Precise->Inner)->GetPropertyValue(Values(Precise).GetRawPtr(0))==1.23456789012345;Pass &= Values(Flags).Num()==2 && CastFieldChecked<FBoolProperty>(Flags->Inner)->GetPropertyValue(Values(Flags).GetRawPtr(0)) && !CastFieldChecked<FBoolProperty>(Flags->Inner)->GetPropertyValue(Values(Flags).GetRawPtr(1));Pass &= Values(Labels).Num()==2 && CastFieldChecked<FStrProperty>(Labels->Inner)->GetPropertyValue(Values(Labels).GetRawPtr(0))==TEXT("Hello 世界") && CastFieldChecked<FStrProperty>(Labels->Inner)->GetPropertyValue(Values(Labels).GetRawPtr(1))==TEXT("quote \" comma,");Pass &= Values(Names).Num()==1 && CastFieldChecked<FNameProperty>(Names->Inner)->GetPropertyValue(Values(Names).GetRawPtr(0))==TEXT("CaseKey");return Pass;}
bool CheckDasStringMapValues(UScriptStruct* Tree,void* Memory){auto Get=[&](const TCHAR* Name){return CastField<FMapProperty>(FindDasStructField(Tree,Name));};auto* IS=Get(TEXT("TextById"));if(!IS)return true;auto* SI=Get(TEXT("CountByText"));auto* SS=Get(TEXT("TextByText"));if(!SI || !SS)return false;FScriptMapHelper A(IS,IS->ContainerPtrToValuePtr<void>(Memory)),B(SI,SI->ContainerPtrToValuePtr<void>(Memory)),C(SS,SS->ContainerPtrToValuePtr<void>(Memory));bool Pass=A.Num()==2 && B.Num()==3 && C.Num()==2;int32 K=-2;int32 I=A.FindMapIndexWithKey(&K);Pass &= I!=INDEX_NONE && CastFieldChecked<FStrProperty>(IS->ValueProp)->GetPropertyValue(A.GetValuePtr(I))==TEXT("Hello 世界");K=0;I=A.FindMapIndexWithKey(&K);Pass &= I!=INDEX_NONE && CastFieldChecked<FStrProperty>(IS->ValueProp)->GetPropertyValue(A.GetValuePtr(I)).IsEmpty();for(const auto& P:TArray<TPair<FString,int32>>{{TEXT("Case"),1},{TEXT("other"),2},{TEXT("Ключ 世界"),3}}){I=B.FindMapIndexWithKey(&P.Key);Pass &= I!=INDEX_NONE && CastFieldChecked<FIntProperty>(SI->ValueProp)->GetPropertyValue(B.GetValuePtr(I))==P.Value;}FString Key=TEXT("");I=C.FindMapIndexWithKey(&Key);Pass &= I!=INDEX_NONE && CastFieldChecked<FStrProperty>(SS->ValueProp)->GetPropertyValue(C.GetValuePtr(I))==TEXT("empty key");Key=TEXT("ключ");I=C.FindMapIndexWithKey(&Key);Pass &= I!=INDEX_NONE && CastFieldChecked<FStrProperty>(SS->ValueProp)->GetPropertyValue(C.GetValuePtr(I))==TEXT("quote \" comma, 世界");return Pass;}
bool CheckDasSetValues(UScriptStruct* Tree,void* Memory){
 auto* Ints=CastField<FSetProperty>(FindDasStructField(Tree,TEXT("UniqueInts")));
 auto* Strings=CastField<FSetProperty>(FindDasStructField(Tree,TEXT("UniqueTexts")));
 auto* Empty=CastField<FSetProperty>(FindDasStructField(Tree,TEXT("EmptySet")));
 if(!Ints || !Strings || !Empty || !Ints->ElementProp->IsA<FIntProperty>() || !Strings->ElementProp->IsA<FStrProperty>())return false;
 FScriptSetHelper A(Ints,Ints->ContainerPtrToValuePtr<void>(Memory)),B(Strings,Strings->ContainerPtrToValuePtr<void>(Memory)),C(Empty,Empty->ContainerPtrToValuePtr<void>(Memory));
 bool Pass=A.Num()==2 && B.Num()==3 && C.Num()==0;
 for(int32 K:TArray<int32>{-3,7})Pass &= A.FindElementIndex(&K)!=INDEX_NONE;
 int32 Removed=42;Pass &= A.FindElementIndex(&Removed)==INDEX_NONE;
 for(const FString& K:TArray<FString>{TEXT(""),TEXT("Case"),TEXT("Ключ 世界")})Pass &= B.FindElementIndex(&K)!=INDEX_NONE;
 return Pass;
}
bool CheckDasScalarMapValues(UScriptStruct* Tree,void* Memory){
 bool Pass=true;
 for(bool TextKey:{false,true}){
  const FString Prefix=TextKey?TEXT("Text"):TEXT("Int");
  for(const FString& Suffix:TArray<FString>{TEXT("Floats"),TEXT("Doubles"),TEXT("Bools"),TEXT("Names")}){
   auto* P=CastField<FMapProperty>(FindDasStructField(Tree,Prefix+Suffix));if(!P)return false;
   FScriptMapHelper Values(P,P->ContainerPtrToValuePtr<void>(Memory));Pass &= Values.Num()==2;
   for(int32 Ordinal=0;Ordinal<2;++Ordinal){
    int32 IntKey=Ordinal==0?-1:0;FString StringKey=Ordinal==0?TEXT("Ключ 世界"):TEXT("");
    const int32 I=TextKey?Values.FindMapIndexWithKey(&StringKey):Values.FindMapIndexWithKey(&IntKey);
    if(I==INDEX_NONE){Pass=false;continue;}const void* V=Values.GetValuePtr(I);
    if(Suffix==TEXT("Floats")){auto* T=CastField<FFloatProperty>(P->ValueProp);Pass &= T && T->GetPropertyValue(V)==(Ordinal==0?1.25f:-0.5f);}
    else if(Suffix==TEXT("Doubles")){auto* T=CastField<FDoubleProperty>(P->ValueProp);Pass &= T && T->GetPropertyValue(V)==(Ordinal==0?1.23456789012345:-9.87654321098765);}
    else if(Suffix==TEXT("Bools")){auto* T=CastField<FBoolProperty>(P->ValueProp);Pass &= T && T->GetPropertyValue(V)==(Ordinal==0);}
    else{auto* T=CastField<FNameProperty>(P->ValueProp);Pass &= T && T->GetPropertyValue(V)==(Ordinal==0?FName(TEXT("CaseKey_17")):NAME_None);}
   }
  }
 }
 return Pass;
}
